```typescript
import { test, expect } from '@playwright/test';

test.describe('Change Email Address with Confirmation', () => {
  const testEmail = 'user@example.com';
  const newEmail = 'newemail@example.com';
  const confirmationCode = '123456';

  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login with test user
    await page.getByLabel('Email').fill(testEmail);
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for dashboard to load
    await page.waitForURL('/dashboard');
  });

  test('should display change email option in profile settings', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile/i }).click();
    await page.getByRole('link', { name: /settings/i }).click();

    // Verify we're on settings page
    await expect(page).toHaveURL('/settings');

    // Check for change email section
    const changeEmailSection = page.getByRole('heading', { name: /change email/i });
    await expect(changeEmailSection).toBeVisible();

    // Verify current email is displayed
    const currentEmailDisplay = page.getByText(testEmail);
    await expect(currentEmailDisplay).toBeVisible();
  });

  test('should initiate email change with new email address', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile/i }).click();
    await page.getByRole('link', { name: /settings/i }).click();

    // Find and click change email button
    const changeEmailButton = page.getByRole('button', { name: /change email/i });
    await expect(changeEmailButton).toBeVisible();
    await changeEmailButton.click();

    // Verify modal or form appears
    const emailInput = page.getByLabel(/new email/i);
    await expect(emailInput).toBeVisible();

    // Enter new email address
    await emailInput.fill(newEmail);

    // Click continue/next button
    const continueButton = page.getByRole('button', { name: /continue|next/i });
    await continueButton.click();

    // Verify confirmation step appears
    const confirmationHeading = page.getByRole('heading', { name: /confirm|verification/i });
    await expect(confirmationHeading).toBeVisible();
  });

  test('should complete email change with confirmation code', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile/i }).click();
    await page.getByRole('link', { name: /settings/i }).click();

    // Initiate email change
    const changeEmailButton = page.getByRole('button', { name: /change email/i });
    await changeEmailButton.click();

    // Enter new email
    const emailInput = page.getByLabel(/new email/i);
    await emailInput.fill(newEmail);

    // Click continue
    const continueButton = page.getByRole('button', { name: /continue|next/i });
    await continueButton.click();

    // Wait for confirmation code input to appear
    const codeInput = page.getByLabel(/confirmation code|verification code/i);
    await expect(codeInput).toBeVisible();

    // Enter confirmation code
    await codeInput.fill(confirmationCode);

    // Click confirm button
    const confirmButton = page.getByRole('button', { name: /confirm|verify/i });
    await confirmButton.click();

    // Verify success message
    const successMessage = page.getByText(/email.*changed|successfully updated/i);
    await expect(successMessage).toBeVisible();

    // Verify new email is now displayed
    const updatedEmailDisplay = page.getByText(newEmail);
    await expect(updatedEmailDisplay).toBeVisible();
  });

  test('should show error for invalid confirmation code', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile/i }).click();
    await page.getByRole('link', { name: /settings/i }).click();

    // Initiate email change
    const changeEmailButton = page.getByRole('button', { name: /change email/i });
    await changeEmailButton.click();

    // Enter new email
    const emailInput = page.getByLabel(/new email/i);
    await emailInput.fill(newEmail);

    // Click continue
    const continueButton = page.getByRole('button', { name: /continue|next/i });
    await continueButton.click();

    // Enter invalid confirmation code
    const codeInput = page.getByLabel(/confirmation code|verification code/i);
    await codeInput.fill('000000');

    // Click confirm button
    const confirmButton = page.getByRole('button', { name: /confirm|verify/i });
    await confirmButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/invalid|incorrect|code/i);
    await expect(errorMessage).toBeVisible();

    // Verify email was not changed
    const oldEmailDisplay = page.getByText(testEmail);
    await expect(oldEmailDisplay).toBeVisible();
  });

  test('should allow resending confirmation code', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile/i }).click();
    await page.getByRole('link', { name: /settings/i }).click();

    // Initiate email change
    const changeEmailButton = page.getByRole('button', { name: /change email/i });
    await changeEmailButton.click();

    // Enter new email
    const emailInput = page.getByLabel(/new email/i);
    await emailInput.fill(newEmail);

    // Click continue
    const continueButton = page.getByRole('button', { name: /continue|next/i });
    await continueButton.click();

    // Wait for confirmation code input
    const codeInput = page.getByLabel(/confirmation code|verification code/i);
    await expect(codeInput).toBeVisible();

    // Click resend code button
    const resendButton = page.getByRole('button', { name: /resend|send again/i });
    await expect(resendButton).toBeVisible();
    await resendButton.click();

    // Verify resend confirmation message
    const resendMessage = page.getByText(/code.*sent|resent/i);
    await expect(resendMessage).toBeVisible();
  });

  test('should cancel email change process', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile/i }).click();
    await page.getByRole('link', { name: /settings/i }).click();

    // Initiate email change
    const changeEmailButton = page.getByRole('button', { name: /change email/i });
    await changeEmailButton.click();

    // Verify modal/form is visible
    const emailInput = page.getByLabel(/new email/i);
    await expect(emailInput).toBeVisible();

    // Click cancel button
    const cancelButton = page.getByRole('button', { name: /cancel|close/i });
    await cancelButton.click();

    // Verify modal is closed and we're back to settings
    await expect(emailInput).not.toBeVisible();

    // Verify original email is still displayed
    const originalEmailDisplay = page.getByText(testEmail);
    await expect(originalEmailDisplay).toBeVisible();
  });
});
